'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function all(chunks, opts) {
  const p = createParser(opts);
  const out = [];
  for (const c of chunks) out.push(...p.push(c));
  out.push(...p.end());
  return out;
}
function everySplit(text, expected, opts) {
  assert.deepEqual(all([text], opts), expected, JSON.stringify(text));
  for (let i = 0; i <= text.length; i++)
    for (let j = i; j <= text.length; j++)
      assert.deepEqual(all([text.slice(0, i), '', text.slice(i, j), text.slice(j)], opts), expected, `${JSON.stringify(text)} ${i} ${j}`);
}
function lineErr(text, n) {
  for (let i = 0; i <= text.length; i++) {
    assert.throws(() => all([text.slice(0, i), text.slice(i)]), e => e instanceof SyntaxError && e.message.includes(`line ${n}`), `${JSON.stringify(text)} ${i}`);
  }
}

everySplit('', []);
everySplit('\uFEFF', []);
everySplit('\n', [['']]);
everySplit('\n\n', [[''], ['']]);
everySplit('\r\n\r\n', [[''], ['']]);
everySplit('\r\r', [[''], ['']]);
everySplit('a\r\nb\rc\nd', [['a'], ['b'], ['c'], ['d']]);
everySplit('\uFEFFa,\uFEFFb\n', [['a', '\uFEFFb']]);
everySplit('"x""y","a\r\nb\rc",d"e"\n', [['x"y', 'a\r\nb\rc', 'd"e"']]);
everySplit('"",""""\r\n,', [['', '"'], ['', '']]);
everySplit('a;"b;c"\n', [['a', 'b;c']], { delimiter: ';' });
everySplit('a\tb', [['a', 'b']], { delimiter: '\t' });

lineErr('a\r\n"b"x', 2);
lineErr('"a\r\nb\rc\nd" ,', 4);
lineErr('x\n"abc\r\n', 3);
lineErr('"a" ', 1);

// incremental emission
const p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), Error);
assert.throws(() => createParser().push(1), TypeError);
for (const d of ['"', '\r', '\n', '', ',,', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);

// header mode
const frozen = parse('x,x,x_2,x\n1,2\n', { header: true });
assert.deepEqual(frozen, [{ x: '1', x_2: '2', x_2_2: '', x_3: '' }]);
const proto = parse('__proto__,a\n1,2', { header: true })[0];
assert.ok(Object.hasOwn(proto, '__proto__') && Object.getPrototypeOf(proto) === Object.prototype);
assert.deepEqual(parse('', { header: true }), []);
console.log('smoke ok');
